import{c as t,Q as o,j as n,m as a}from"./chunks/framework.BqPkuuVc.js";const r="/assets/docs-run-core-station-before-event.CqxjA9U4.png",s="/assets/docs-run-core-station-applied.BwyraAJV.png",i="/assets/docs-run-core-station-finish.CTzfdsBM.png",d="/assets/docs-run-core-station-no-record-dialog.BVINmQaH.png",h="/assets/docs-run-core-station-marked.DHT6UIYs.png",c="/assets/docs-run-core-station-left-out.hd5zZQYf.png",l="/assets/docs-run-core-station-choose.Dm1wfCuj.png",k=JSON.parse('{"title":"Station memory","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/station-memory.md","filePath":"user/running-the-event/station-memory.md"}'),g={name:"user/running-the-event/station-memory.md"};function u(p,e,m,y,f,w){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="station-memory" tabindex="-1">Station memory <a class="header-anchor" href="#station-memory" aria-label="Permalink to &quot;Station memory&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators reading a SportIdent unit&#39;s memory: to account for everyone, recover punches the radio missed, or check a unit&#39;s clock.</p><p>Every SportIdent control unit keeps a backup of every card that punched it. Reading that memory into Manager tells you, for certain, who punched the start, the check or the finish, even when the radio didn&#39;t hear them.</p><h2 id="reading-the-start-or-check-box-the-standard-way" tabindex="-1">Reading the start or check box: the standard way <a class="header-anchor" href="#reading-the-start-or-check-box-the-standard-way" aria-label="Permalink to &quot;Reading the start or check box: the standard way&quot;">​</a></h2><p>The whole job, normally:</p><ol><li><strong>Before the event</strong>, on each unit: <strong>Set to PC time</strong>, then <strong>Clear memory</strong>.</li><li><strong>Once everyone has started</strong>, put the start or check unit on the reader and click <strong>Read and apply</strong>. One click.</li><li>Under <strong>Who is accounted for</strong>, click <strong>Review</strong> beside <strong>No record of starting</strong>, and <strong>Mark as DNS</strong>.</li></ol><p>Everyone who went out is now on your <strong>On course</strong> list, and everyone who didn&#39;t is DNS. The rest of this page shows each thing the screen can tell you along the way, and what to do about it. Most of them need nothing from you.</p><h2 id="when-to-read-a-station" tabindex="-1">When to read a station <a class="header-anchor" href="#when-to-read-a-station" aria-label="Permalink to &quot;When to read a station&quot;">​</a></h2><ul><li><strong>After the start, to find the non-starters.</strong> Read the <strong>check</strong> or <strong>start</strong> unit: anyone entered who isn&#39;t in it, and nothing else has seen, didn&#39;t start.</li><li><strong>At the end of the day, to account for everyone.</strong> Read the <strong>finish</strong> unit: anyone in it came back. See <a href="./safety-check#reading-sportident-stations">Safety check</a>.</li><li><strong>When a radio control or radio finish missed people</strong>, or you suspect a unit misbehaved.</li></ul><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A SportIdent USB station (a BSM7 or BSM8) plugged into the computer you&#39;re using, and connected in the browser. Manager calls it the <strong>direct station</strong>; it&#39;s the same reader card download uses.</li><li>The <strong>coupling rod</strong>, to connect it to the unit you&#39;re reading, which Manager calls the <strong>remote station</strong>.</li><li>A browser with Web Serial: Chrome, Edge, or Firefox 151 or later. On a computer other than the server, use the secure link (see <a href="./../reference/https-and-certificates">HTTPS and certificates</a>). On a Mac you also need the CP210x driver (see <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>).</li></ul><p><strong>One reader serves the whole of Manager.</strong> Connect the station here, on the dashboard&#39;s <strong>Download card</strong> tile, on the <strong>Card downloads</strong> page or on <strong>Station configuration</strong>, and it&#39;s the same reader everywhere, with card download still working. Card downloads pause while a memory is read, cleared or a clock set, and carry on afterwards. A card presented during one of those isn&#39;t downloaded and has to be presented again, and a memory read is refused while a card is being downloaded. Disconnecting here disconnects card download too.</p><h2 id="the-station-clock" tabindex="-1">The station clock <a class="header-anchor" href="#the-station-clock" aria-label="Permalink to &quot;The station clock&quot;">​</a></h2><p>Open the event and choose <strong>SportIdent station</strong> from the event menu&#39;s <strong>Race</strong> mode, under <strong>Admin</strong>. The screen is three boxes. The top one is the reader, and says whether it&#39;s connected. <strong>Station clock</strong> comes next, because that&#39;s the job before the start.</p><p><img src="'+r+'" alt="The SportIdent station screen before the event: the connected reader, and a Station clock box with Set to PC time, Clear memory and Read time"></p><ul><li><strong>Set to PC time</strong> sets the unit&#39;s clock to this computer&#39;s.</li><li><strong>Clear memory</strong> erases every record in the unit, after you confirm. It can&#39;t be undone: clear a unit before an event, so last event&#39;s cards don&#39;t appear in it, and only after you&#39;ve read anything you might need.</li><li><strong>Read time</strong> shows the unit&#39;s clock and how far it is ahead of or behind this computer.</li></ul><p>Whatever the unit is doing shows under the buttons, with a progress bar.</p><p><strong>What to do:</strong> nothing to decide. Set the time, clear the memory, next unit. A unit with the wrong time puts every punch in the wrong place. If one was out on the day, correct its punches with a <strong>Time Offset</strong> on the control rather than changing the unit&#39;s clock afterwards (see <a href="./../event-setup/controls-and-radio-controls#time-offset">Time Offset</a>). Don&#39;t clear a unit during an event: its memory is the backup for the radio.</p><p>Until the event is started there&#39;s no <strong>Station memory</strong> box: there&#39;s nothing in a unit to read yet.</p><h2 id="reading-a-station" tabindex="-1">Reading a station <a class="header-anchor" href="#reading-a-station" aria-label="Permalink to &quot;Reading a station&quot;">​</a></h2><p>Once the event has started, <strong>Station memory</strong> appears below the clock. Place the unit you&#39;re reading against the reader with the coupling rod, and click <strong>Read and apply</strong>. Manager reads the whole memory, applies every punch from today, and says what it did in a few sentences.</p><p><img src="'+s+'" alt="After Read and apply on a start unit: 8 records applied, three runners added who nobody had entered, one of them as Unknown, and Who is accounted for listing 6 competitors with no record of starting and 1 still out"></p><p><strong>What to do:</strong> nothing, for the runners it added: they&#39;re on the list to account for. Every runner named is a link: click a name, or <strong>Unknown</strong>, to open that competitor.</p><p>Reading the same unit again is safe. Anything already applied is recognised and left alone, and the result says &quot;Nothing new&quot;.</p><h3 id="what-applying-does" tabindex="-1">What applying does <a class="header-anchor" href="#what-applying-does" aria-label="Permalink to &quot;What applying does&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Unit</th><th>What applying does</th></tr></thead><tbody><tr><td><strong>Start</strong></td><td>Someone not yet started is marked <strong>On course</strong>.</td></tr><tr><td><strong>Check</strong></td><td>They&#39;re checked in, and counted on your On course list until they&#39;re back. Their status doesn&#39;t change.</td></tr><tr><td><strong>Finish</strong></td><td>Anyone with no status, or still on course, is marked <strong>DNF</strong>: they came back, but there&#39;s no result until their card is downloaded.</td></tr></tbody></table><p>A finished competitor, or one with a status you set, isn&#39;t changed, except that a <strong>DNS</strong> nothing had seen is taken back when a station shows them, and the result names them. The full rules, and why the order you read stations in doesn&#39;t matter, are in <a href="./safety-check#applying-station-records-also-changes-status">Applying station records also changes status</a>.</p><p>A card used for more than one run gives each run its own record: when a sibling borrows a card, or one person runs twice, each entry gets the punch from their own run (see <a href="./who-is-still-on-course#more-than-one-run-on-a-card">More than one run on a card</a>).</p><h3 id="cards-nobody-is-entered-on" tabindex="-1">Cards nobody is entered on <a class="header-anchor" href="#cards-nobody-is-entered-on" aria-label="Permalink to &quot;Cards nobody is entered on&quot;">​</a></h3><p>A card a <strong>start</strong> or <strong>check</strong> unit saw that nobody in the event holds is added as a competitor, so a runner nobody entered is on the list to account for.</p><p>A card the <a href="./../reference/competitor-registry">competitor registry</a> knows is added as that person, with their club and Eventor ID, just as a card download would name them. Any other card is added as <strong>Unknown</strong>: a card two people in the registry are recorded with, a <a href="./hire-items">hire card</a>, a card the registry has never seen, or any card at an event that <a href="./../event-setup/low-key-events#ignore-competitor-registry">ignores the registry</a>.</p><p><strong>What to do:</strong> when an Unknown comes in and downloads, click <strong>Unknown</strong> in the result (or open them from the competitor list) and pick their name from <strong>First name</strong>: that links them to the registry (<a href="./../event-setup/competitors-clubs-teams">Editing a competitor</a>). The registry only knows who a card <em>belongs to</em>, so a runner on a borrowed card is added under the owner&#39;s name; correct it when they come in.</p><p>A <strong>finish</strong> unit adds nobody. A card that came back but isn&#39;t entered is only named: they came back, so there&#39;s nobody to look for.</p><p><img src="'+i+'" alt="After Read and apply on a finish unit: 2 records applied, and 1 card came in that nobody is entered on"></p><p><strong>What to do:</strong> only if they should have been entered. Then add them on the <strong>Competitors</strong> page.</p><h2 id="who-is-accounted-for" tabindex="-1">Who is accounted for <a class="header-anchor" href="#who-is-accounted-for" aria-label="Permalink to &quot;Who is accounted for&quot;">​</a></h2><p>Once a start, check or finish unit has been read in full, <strong>Who is accounted for</strong> appears under the result, and keeps itself up to date:</p><ul><li><strong>No record of starting</strong>: entered competitors nothing has seen. After the start or check unit is read with everyone gone, these are your non-starters.</li><li><strong>Still out</strong>: competitors something saw go out, and nothing has seen come back. After the finish unit is read, this is the list to chase.</li></ul><p><strong>Review</strong> beside <strong>No record of starting</strong> opens the list:</p><p><img src="'+d+'" alt="The No record of starting list: six competitors, each ticked, with their class, card number and start time, and a Mark as DNS (6) button"></p><p>Everyone with a start time starts ticked. A punching start gives nobody a start time, so the list opens with nobody ticked: the box in the header ticks them all.</p><p><strong>What to do:</strong> this is the one real decision in the normal flow. Untick anyone you know started, then click <strong>Mark as DNS</strong>. The result is confirmed in one line, and they&#39;re gone from the list:</p><p><img src="'+h+'" alt="Who is accounted for after marking: 1 competitor still out, and Marked 6 competitors as DNS"></p><p>If a later station read shows one of them, their DNS is taken back. If some of the memory&#39;s records weren&#39;t applied, the panel says how many, because they may name someone it lists as unseen. See <a href="./safety-check#who-is-accounted-for">Who is accounted for</a>.</p><h2 id="records-read-and-apply-leaves-out" tabindex="-1">Records Read and apply leaves out <a class="header-anchor" href="#records-read-and-apply-leaves-out" aria-label="Permalink to &quot;Records Read and apply leaves out&quot;">​</a></h2><p>Read and apply only takes punches it can trust as today&#39;s. Anything else is set aside and explained in one line, with the one button that answers it beside it.</p><p><img src="'+c+'" alt="A Read and apply result: 8 records applied, 1 card with no time stored, 2 records from another day and 1 with an unreadable date (each with Apply anyway), and 1 record that wasn&#39;t a punch"></p><table tabindex="0"><thead><tr><th>The line says</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td>No time was stored</td><td>The card touched the unit, but it saved no time.</td><td>Nothing: it&#39;s applied, so they count as seen, with no time.</td></tr><tr><td>From another day</td><td>The unit wasn&#39;t cleared after an earlier event.</td><td>Usually nothing. <strong>Reading a station the day after the event?</strong> Click <strong>Apply anyway</strong>.</td></tr><tr><td>A date that couldn&#39;t be read</td><td>The record may be damaged; nothing says which day it was.</td><td><strong>Apply anyway</strong> if they could have been here. It counts as seen, and its time is never used.</td></tr><tr><td>Wasn&#39;t a punch</td><td>Half of a record the unit wrote while its clock was being set.</td><td>Nothing.</td></tr><tr><td>Couldn&#39;t apply</td><td>The server refused the record; each card is listed with the reason.</td><td><strong>Try again</strong> sends just those again.</td></tr></tbody></table><h2 id="choosing-records-yourself" tabindex="-1">Choosing records yourself <a class="header-anchor" href="#choosing-records-yourself" aria-label="Permalink to &quot;Choosing records yourself&quot;">​</a></h2><p>For the rare case where you don&#39;t want the whole of today, such as a card you know wasn&#39;t at today&#39;s event, click <strong>Read and choose records…</strong> instead. Manager reads the unit without applying anything and opens its records, the ones Read and apply would take already ticked.</p><p><img src="'+l+'" alt="Station records: Today only switched off, Not applied selected, four records from today ticked and one from last week unticked, with Apply selected (4)"></p><p><strong>What to do:</strong> untick what doesn&#39;t belong, then <strong>Apply selected</strong>. <strong>Today only</strong> hides records from other days; <strong>Not applied</strong> and <strong>All</strong> switch between what&#39;s still to apply and everything in the memory. <strong>Show all records</strong>, under any result, opens the same list.</p><h2 id="recovered-punches-and-radio-punches" tabindex="-1">Recovered punches and radio punches <a class="header-anchor" href="#recovered-punches-and-radio-punches" aria-label="Permalink to &quot;Recovered punches and radio punches&quot;">​</a></h2><p>A station download is kept separately from the radio punches. A runner whose finish the radio already heard isn&#39;t counted twice, and the card download still decides their result.</p><h2 id="when-something-goes-wrong" tabindex="-1">When something goes wrong <a class="header-anchor" href="#when-something-goes-wrong" aria-label="Permalink to &quot;When something goes wrong&quot;">​</a></h2><ul><li><strong>&quot;The direct station was left in an unknown mode&quot;.</strong> Reading switches the direct station to remote mode and back. If that was interrupted, disconnect the reader and connect it again, from here or anywhere else. Card downloads may not work until you do.</li><li><strong>&quot;This station is in … mode, so its memory holds whole card images&quot;.</strong> A unit set up to store card images keeps nothing Manager can read back.</li><li><strong>&quot;The station&#39;s memory has filled and wrapped&quot;.</strong> The oldest records were overwritten by newer ones and are gone. Read units more often, or clear them before each event.</li><li><strong>A read stops part-way, or reports the wrong part of the memory.</strong> Check the coupling rod is seated, then read the memory again.</li><li><strong>&quot;Only a start, check or finish unit can be applied&quot;.</strong> You&#39;ve read a control unit. Its records are under <strong>Show all records</strong>; swap in the unit you meant to read.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./safety-check">Safety check: accounting for everyone</a></li><li><a href="./who-is-still-on-course">Who is still on course</a></li><li><a href="./radio-punches">Radio punches</a></li><li><a href="./card-download">Downloading cards</a></li><li><a href="./../reference/station-configuration">Station configuration</a> — setting a unit&#39;s code, mode and switch-off time, and programming many units at once</li><li><a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a></li></ul>',58)])])}const v=t(g,[["render",u]]);export{k as __pageData,v as default};
